import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md","lastUpdated":0}`),a={name:`guide/changelog.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><h2 id="version-2-4-4" tabindex="-1">Version 2.4.4 <a class="header-anchor" href="#version-2-4-4" aria-label="Permalink to “Version 2.4.4”">​</a></h2><hr><p>Release date: 2025-11-21</p><ul><li>Minor detail improvements</li><li>Added .NET 10.0 support</li></ul><h2 id="version-2-4-3" tabindex="-1">Version 2.4.3 <a class="header-anchor" href="#version-2-4-3" aria-label="Permalink to “Version 2.4.3”">​</a></h2><hr><p>Release date: 2025-05-21</p><ul><li>Added file monitoring</li><li>Fixed known bugs</li><li>Added .NET 9.0 support</li></ul><h2 id="version-2-4-2" tabindex="-1">Version 2.4.2 <a class="header-anchor" href="#version-2-4-2" aria-label="Permalink to “Version 2.4.2”">​</a></h2><hr><p>Release date: 2023-12-25</p><ul><li>Fixed an exception in <code>decimal</code> logical operations</li><li>Fixed incorrect formatting in some cases when the output mode is set to Auto</li><li>Added .NET 8.0 support</li><li>Other code optimizations</li></ul><h2 id="version-2-4-1" tabindex="-1">Version 2.4.1 <a class="header-anchor" href="#version-2-4-1" aria-label="Permalink to “Version 2.4.1”">​</a></h2><hr><p>Release date: 2023-10-22</p><ul><li>Fixed known bugs</li><li>Adjusted the custom tag interfaces</li><li>Improved anonymous object support</li><li>Improved automatic parameter type inference</li><li>Other code optimizations</li></ul><h2 id="version-2-3-3" tabindex="-1">Version 2.3.3 <a class="header-anchor" href="#version-2-3-3" aria-label="Permalink to “Version 2.3.3”">​</a></h2><hr><p>Release date: 2023-01-29</p><ul><li>Fixed known bugs</li><li>Code optimizations</li></ul><h2 id="version-2-3-2" tabindex="-1">Version 2.3.2 <a class="header-anchor" href="#version-2-3-2" aria-label="Permalink to “Version 2.3.2”">​</a></h2><hr><p>Release date: 2022-11-04</p><ul><li>Fixed known bugs</li></ul><h2 id="version-2-3-1" tabindex="-1">Version 2.3.1 <a class="header-anchor" href="#version-2-3-1" aria-label="Permalink to “Version 2.3.1”">​</a></h2><hr><p>Release date: 2022-09-13</p><ul><li>Added automatic conversion to nullable types</li><li>Re-added .NET Framework 2.0 / .NET Framework 3.5 support</li><li>Other known issue fixes</li></ul><h2 id="version-2-3-0" tabindex="-1">Version 2.3.0 <a class="header-anchor" href="#version-2-3-0" aria-label="Permalink to “Version 2.3.0”">​</a></h2><hr><p>Release date: 2022-05-10</p><ul><li>Added the array tag, allowing simple arrays to be defined in templates</li><li>Fixed an issue where some method calls threw exceptions under .NET 6.0</li><li>Adjusted the methods for switching between the compile engine and the interpretation engine, improved async support</li><li>Other known issue fixes</li></ul><h2 id="version-2-2-5" tabindex="-1">Version 2.2.5 <a class="header-anchor" href="#version-2-2-5" aria-label="Permalink to “Version 2.2.5”">​</a></h2><hr><p>Release date: 2021-12-08</p><ul><li><code>ResourceDirectories</code> configuration adjustments</li></ul><h2 id="version-2-2-4" tabindex="-1">Version 2.2.4 <a class="header-anchor" href="#version-2-2-4" aria-label="Permalink to “Version 2.2.4”">​</a></h2><hr><p>Release date: 2021-11-28</p><ul><li>Improved dynamic access in the interpretation engine</li><li>Improved async function support</li><li>Improved template caching; compiled results can now be excluded from the cache while debugging</li><li>Improved <code>DataTable</code> support</li><li>Added the <code>Engine.Parse</code> entry point</li><li>Added .NET 6.0 support</li><li>Other known issue fixes</li></ul><h2 id="version-2-2-2" tabindex="-1">Version 2.2.2 <a class="header-anchor" href="#version-2-2-2" aria-label="Permalink to “Version 2.2.2”">​</a></h2><hr><p>Release date: 2021-07-26</p><ul><li>Added anonymous object support</li><li>Configuration adjustments, removed deprecated options</li><li>Feature improvements</li></ul><h2 id="version-2-2-0" tabindex="-1">Version 2.2.0 <a class="header-anchor" href="#version-2-2-0" aria-label="Permalink to “Version 2.2.0”">​</a></h2><hr><p>Release date: 2021-06-08</p><ul><li>Fixed tag parsing issues in specific cases</li><li>Fixed an issue where <code>foreach</code> inferred the wrong type for certain types</li><li>Added the tag output mode (<code>OutMode</code>) configuration</li><li>Improved exception messages</li><li>Configuration adjustments, code optimizations</li></ul><h2 id="version-2-1-2" tabindex="-1">Version 2.1.2 <a class="header-anchor" href="#version-2-1-2" aria-label="Permalink to “Version 2.1.2”">​</a></h2><hr><p>Release date: 2021-05-19</p><ul><li><ol><li>Fixed comparison of two string constants not matching</li></ol></li><li><ol start="2"><li>Fixed the <code>Configure(Action&lt;IConfig, VariableScope&gt;)</code> configuration method not taking effect</li></ol></li><li><ol start="3"><li>Improved the parser and related code</li></ol></li></ul><h2 id="version-2-1-0" tabindex="-1">Version 2.1.0 <a class="header-anchor" href="#version-2-1-0" aria-label="Permalink to “Version 2.1.0”">​</a></h2><hr><p>Release date: 2021-04-09</p><ul><li><ol><li>Fixed known bugs</li></ol></li><li><ol start="2"><li>Feature improvements</li></ol></li></ul><h2 id="version-2-0-0" tabindex="-1">Version 2.0.0 <a class="header-anchor" href="#version-2-0-0" aria-label="Permalink to “Version 2.0.0”">​</a></h2><hr><p>Release date: 2021-02-04</p><ul><li><p>Features</p><ul><li><ol><li>Architecture and interface adjustments: refactored from an interpreting template engine into a compiled template engine</li></ol></li><li><ol start="2"><li>Pre-compilation is supported; templates that are not pre-compiled are compiled automatically on first execution</li></ol></li><li><ol start="3"><li>Added the loader concept: with a custom loader, templates can be loaded from files, FTP, HTTP and many other ways and paths</li></ol></li><li><ol start="4"><li>Added the layout tag, similar to layout in Razor or master pages in aspx (block in other template engines)</li></ol></li><li><ol start="5"><li>Added index syntax such as <code>row[&quot;name&quot;]</code>; for backward compatibility, the original <code>row.name</code> is still supported in this version</li></ol></li><li><ol start="6"><li>Added async method support, allowing templates to call async methods</li></ol></li><li><ol start="7"><li>Added static method support, allowing templates to call static methods</li></ol></li></ul></li><li><p>Improvements</p><ul><li><ol><li>Structure optimization, performance improvements</li></ol></li></ul></li><li><p>Other</p><ul><li>Note: from this version on, frameworks below <code>.net framework 4.0</code> (.net framework 2.0/3.5) are no longer supported</li><li>Note: this is a major version upgrade and some interfaces are no longer compatible; please consider the risks before upgrading</li><li>Supported frameworks are adjusted as follows:</li><li><ol><li><code>.net framework 4.0</code> or above, or the corresponding Mono version</li></ol></li><li><ol start="2"><li><code>.net core 2.1</code> or above</li></ol></li><li><ol start="3"><li><code>.netstandard 2.1</code> or above</li></ol></li><li><ol start="4"><li><code>.net 5.0</code></li></ol></li></ul></li></ul><h2 id="version-1-4-0" tabindex="-1">Version 1.4.0 <a class="header-anchor" href="#version-1-4-0" aria-label="Permalink to “Version 1.4.0”">​</a></h2><hr><p>Release date: 2021-01-17</p><ul><li><p>Features</p><ul><li><ol><li>Added the loader concept: with a custom loader, templates can be loaded from files, FTP, HTTP and many other ways and paths</li></ol></li><li><ol start="2"><li>Added the layout tag, similar to layout in Razor or master pages in aspx (block in other template engines)</li></ol></li><li><ol start="3"><li>Added index syntax such as <code>row[&quot;name&quot;]</code>; for backward compatibility, the original <code>row.name</code> is still supported in this version</li></ol></li><li><ol start="4"><li>Fixed a bug where improper handling of logical operations could throw an exception</li></ol></li><li><ol start="5"><li>Added async method support and some .NET Core related features; adjusted the constructors of some classes for easier DI</li></ol></li></ul></li><li><p>Improvements</p><ul><li><ol><li>Simplified the syntax of the foreach and elseif tags (the original syntax is still supported)</li></ol><ul><li><code>foreach in</code> can be shortened to <code>for in</code></li><li><code>elseif</code> can be shortened to <code>elif</code></li></ul></li><li><ol start="2"><li>Adjusted configuration parameters</li></ol></li><li><ol start="3"><li>Adjusted the namespace hierarchy for a clearer structure</li></ol></li><li><ol start="4"><li>Removed some redundant design</li></ol></li></ul></li><li><p>Other</p><ul><li>The license changed from <code>apache 2.0</code> to the simpler and more permissive <code>MIT</code></li><li>This is the long-term support release of 1.X; 1.X will only receive bug fixes from now on</li><li>Supported frameworks are adjusted as follows:</li><li><ol><li>.net framework 2.0 or above</li></ol></li><li><ol start="2"><li>.net core 2.1 or above</li></ol></li><li><ol start="3"><li>.netstandard 2.0 or above</li></ol></li></ul></li></ul><h2 id="version-1-3-3" tabindex="-1">Version 1.3.3 <a class="header-anchor" href="#version-1-3-3" aria-label="Permalink to “Version 1.3.3”">​</a></h2><hr><p>Release date: 2018-04-27</p><ul><li>Fixed a bug in reverse Polish notation expression evaluation</li></ul><h2 id="version-1-3-2" tabindex="-1">Version 1.3.2 <a class="header-anchor" href="#version-1-3-2" aria-label="Permalink to “Version 1.3.2”">​</a></h2><hr><p>Release date: 2017-09-13</p><ul><li>Added .NET Core support (1.1+)</li><li>Fixed unexpected values when evaluating expressions</li><li>Fixed method tags failing to recognize negative arguments</li><li>Added .NET Standard support</li></ul><h2 id="version-1-3-1" tabindex="-1">Version 1.3.1 <a class="header-anchor" href="#version-1-3-1" aria-label="Permalink to “Version 1.3.1”">​</a></h2><hr><p>Release date: 2016-12-01</p><ul><li>Fixed a bug</li><li>Optimized IL (provisional)</li><li>Fixed accessing a non-existent property in a template rendering the parent object</li><li>Adjusted the Engine class <ol><li>Adjusted the <code>Engine.Configure()</code> overloads</li><li>Everything under <code>Engine.Runtime</code> was moved into Engine and <code>Runtime</code> was removed (fewer call layers)</li><li>Added <code>Engine.SetEnvironmentVariable</code> (configure custom variables) and <code>Engine.GetEnvironmentVariable</code> (get custom variables)</li></ol></li></ul><h2 id="version-1-3-0" tabindex="-1">Version 1.3.0 <a class="header-anchor" href="#version-1-3-0" aria-label="Permalink to “Version 1.3.0”">​</a></h2><hr><p>Release date: 2015-10-16</p><ul><li><p>To avoid making the engine overly complicated, the following usages are no longer supported (everything is unified under the Engine static class):</p><ol><li>Loading a template from a specified file: <code>Template.FromFile(String, Encoding)</code> has been removed! Use <code>Engine.LoadTemplate(String,TemplateContext)</code> instead.</li><li>Global configuration entry: the <code>JinianNet.JNTemplate.BuildManager</code> class has been removed! Use <code>Engine.Configure()</code> + 2 overloads instead.</li><li>Template search directories: the <code>Resources.Paths</code>/<code>TemplateContext.Paths</code> properties have been removed! Use <code>Engine.Runtime.ResourceDirectories</code> instead.</li></ol></li><li><p>Feature development:</p><ul><li>Added the engine configuration entry</li><li>Support for tag comments</li><li>Support for custom tag prefix and suffix</li><li>Added a switch for tag whitespace handling</li><li>Added a case-sensitivity switch</li></ul></li></ul><h2 id="version-1-2-3" tabindex="-1">Version 1.2.3 <a class="header-anchor" href="#version-1-2-3" aria-label="Permalink to “Version 1.2.3”">​</a></h2><hr><p>Release date: 2015-09-16</p><ul><li>Adjusted the scope handling of the set tag inside a foreach loop body</li><li>Fixed a bug where expression evaluation threw an exception in a specific case</li><li>Improved formal parameter handling in method tag parsing, added <code>params</code> support</li><li>Fixed a bug in logical operations</li><li>1.2.x will only receive bug fixes from now on</li></ul><h2 id="version-1-2-2" tabindex="-1">Version 1.2.2 <a class="header-anchor" href="#version-1-2-2" aria-label="Permalink to “Version 1.2.2”">​</a></h2><hr><p>Release date: 2014-02-23</p><ul><li><ol><li>Fixed for tag loop errors caused by inaccurate return types in expression evaluation</li></ol></li><li><ol start="2"><li>Fixed string comparison issues caused by spaces</li></ol></li><li><ol start="3"><li>Fixed type restriction issues in IF evaluation</li></ol></li><li><ol start="4"><li>Adjusted a default setting of <code>for</code></li></ol></li><li><ol start="5"><li>Improved unclear exception messages during parsing</li></ol></li></ul><h2 id="version-1-2-1" tabindex="-1">Version 1.2.1 <a class="header-anchor" href="#version-1-2-1" aria-label="Permalink to “Version 1.2.1”">​</a></h2><hr><p>Release date: 2014-08-14</p><ul><li>Bug fixes</li><li>Added exception messages</li><li>Path improvements, Linux compatible</li><li>Version number display adjustments</li></ul><h2 id="version-1-2-0" tabindex="-1">Version 1.2.0 <a class="header-anchor" href="#version-1-2-0" aria-label="Permalink to “Version 1.2.0”">​</a></h2><hr><p>Release date: 2014-07-28</p><ul><li>Added the <code>for</code> tag</li><li>Added <code>elseif</code> support</li><li>Added the <code>Reference</code> tag</li><li>Restructured and optimized part of the tag analysis code</li><li>Added detailed comments</li></ul><h2 id="version-1-1-0" tabindex="-1">Version 1.1.0 <a class="header-anchor" href="#version-1-1-0" aria-label="Permalink to “Version 1.1.0”">​</a></h2><hr><p>Release date: 2013-03-18</p><ul><li>Refactored the overall framework structure, performance optimization</li><li>The tag prefix changed from <code>#{</code> to <code>${</code></li><li>Added shorthand tag support: for example <code>${ Site.Title }</code> can be shortened to <code>$Site.Title</code></li><li>Simplified complex tag syntax: for example <code>#{#if(3&gt;5)}</code> can now be written as <code>${if(3&gt;5)}</code> or shortened to <code>$if(3&gt;5)</code></li><li>Adjusted SET tag syntax: <code>#{set n=5}</code> becomes <code>${set(n=5)}</code> (shorthand: <code>$set(n=5)</code>)</li><li>Added the Include tag!</li></ul><h2 id="version-1-0-3" tabindex="-1">Version 1.0.3 <a class="header-anchor" href="#version-1-0-3" aria-label="Permalink to “Version 1.0.3”">​</a></h2><hr><p>Release date: 2011-12-05</p><ul><li>Initial version</li></ul>',105)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};